window.PUBLIC_MATCH_LOADING={};window.PUBLIC_MATCH_ERRORS={};
async function publicJsonParts(parts){const strings=await Promise.all(parts.map(async u=>{const r=await fetch(u);if(!r.ok)throw Error('数据加载失败：'+r.status);const bytes=new Uint8Array(await r.arrayBuffer());if(bytes[0]===31&&bytes[1]===139){const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return new Response(stream).text()}return new TextDecoder().decode(bytes)}));return JSON.parse(strings.join(''))}
async function publicLoadMatching(id){if(!window.PUBLIC_MANIFEST.matching[id]||window.PUBLIC_MATCH_LOADING[id])return;window.PUBLIC_MATCH_LOADING[id]=true;try{const d=await publicJsonParts(window.PUBLIC_MANIFEST.matching[id]);ADDITIONAL_MATCHING_DATA[id]=d;if(state.storeId===id&&state.tab==='matching')render()}catch(e){window.PUBLIC_MATCH_ERRORS[id]=e.message;if(state.storeId===id&&state.tab==='matching')toast('匹对结果加载失败，请刷新页面重试')}}
(async()=>{try{const r=await fetch('/data/manifest.json?v=20261106-koala-price-review-v1');if(!r.ok)throw Error('目录加载失败');window.PUBLIC_MANIFEST=await r.json();window.PUBLIC_SEED=await publicJsonParts(window.PUBLIC_MANIFEST.catalog);const app=document.createElement('script');app.src='/app.js?v=20261106-koala-price-review-v1';document.body.appendChild(app)}catch(e){document.querySelector('#main').innerHTML='<section class="panel" style="padding:30px"><h2>暂时无法加载资料</h2><p>请检查网络后刷新页面。</p></section>'}})();